/**
 * Generates ids, as a port (rule 10: UUIDv7, generated by the app).
 *
 * Returns plain strings. When the client already sent an id (idempotent create), the
 * handler validates that one with `isUuidV7` instead of generating a new one.
 *
 * Abstract class for the same DI reason as `Clock`.
 */
export abstract class IdGenerator {
  /** Time-ordered UUID, so `ORDER BY id` is roughly chronological. */
  abstract uuidv7(): string;
  /** Short, URL-safe id used in board and ticket URLs (`/b/:shortId`). */
  abstract shortId(): string;
}
